// Define the fractal() function, which recursively draws a fractal
function fractal(x, y, w, h, s, level) {
  // If the level is 0, do nothing
  if (level === 0) {
    return;
  }

  // Draw a smaller fractal at the specified coordinates
  p.fill(255, 0, 0, 255 / level);
  p.beginShape();
  p.vertex(x, y);
  p.bezierVertex(x + w / 2, y, x + w, y + h / 2, x + w, y);
  p.bezierVertex(x + w, y - h / 2, x + w / 2, y, x, y);
  p.endShape(CLOSE);

  // Fractalize the smaller fractal
  fractal(x + w / 4, y + h / 4, w / 2, h / 2, s, level - 1);
  fractal(x - w / 4, y + h / 4, w / 2, h / 2, s, level - 1);
  fractal(x + w / 4, y - h / 4, w / 2, h / 2, s, level - 1);
