\node [block, below of=loss] (bprop) {Backward Propagation};
\node [block, below of=bprop] (update) {Update Parameters};

\node [block, right=1.5cm of init] (evalMode) {Set to Evaluation Mode};
\node [block, below of=evalMode] (inputEval) {Input Data};
\node [block, below of=inputEval] (fpropEval) {Forward Propagation};
\node [block, below of=fpropEval] (lossEval) {Compute Loss};
\node [block, below of=lossEval] (metricsEval) {Calculate Metrics};

% Edges
\path [line] (init) -- (trainMode);
\path [line] (trainMode) -- (input);
\path [line] (input) -- (fprop);
\path [line] (fprop) -- (loss);
\path [line] (loss) -- (bprop);
\path [line] (bprop) -- (update);
\path [line] (update) -- ++(-2,0.0) |- (input);
\path [line] (update) -- ++(-2.5,0) |- (trainMode);

\path [line] (evalMode) -- (inputEval);
\path [line] (inputEval) -- (fpropEval);
\path [line] (fpropEval) -- (lossEval);
\path [line] (lossEval) -- (metricsEval);
\path [line] (metricsEval) -- ++(2,0) |- (inputEval);
\path [line] (metricsEval) -- ++(2.5,0) |- (evalMode);

% Labels
\node[align=center, above=0.5cm of init] {Training process};
\node[align=center, above=0.5cm of evalMode] {Evaluation process};
\node[align=center, left=1.5cm of loss] {Repeat for\\each batch};
\node[align=center, right=1.5cm of lossEval] {Repeat for\\each batch};
\node[align=center, right=1.75cm of inputEval] {Repeat for\\every epoch};
\node[align=center, left=1.75cm of init] {Repeat for\\every epoch};

\end{tikzpicture}
