function switchStatus(error, action, timeToDelay = 0) {
  let plainAction;
  if (isObservable(action)) plainAction = await action.toPromise();
  console.log('\n\n---- Error action ----', plainAction, '\n', action, '\n', error, '\n\n');

  let mensajeError = '';

  switch (error.status) {
    case 0:
    case 504:
    case 502:
    case 503:
      dispatch(generalActions.loading_show());
      setTimeout(() => dispatch(action), timeToDelay + 1000);
      break;
    case 400:
      Sentry.Native.captureMessage('ERROR - 400', {
        extra: { error, plainAction, action },
      });
      dispatch(generalActions.errorAlert('Se produjo un error.'));
      break;
    case 401:
      logEvent('LOGOUT_401');
      dispatch(usersActions.logout());
      break;
    default:
      mensajeError = error?.xhr?._response?.message || error.code || error.name || 'Error desconocido';
      if (!env_production) console.log('Error peticion - ', mensajeError);
      Sentry.Native.captureMessage(mensajeError, {
        extra: { error, plainAction },
      });
  }
  return EMPTY;
}

